105	/// A map from binding names to values.
106	#[derive(Default, Clone)]
107	pub struct Scope {
108	    map: IndexMap<EcoString, Binding, FxBuildHasher>,
109	    deduplicate: bool,
110	    category: Option<Category>,
111	}
112	
113	/// Scope construction.
114	impl Scope {
115	    /// Create a new empty scope.
116	    pub fn new() -> Self {
117	        Self::default()
118	    }
119	
120	    /// Create a new scope with duplication prevention.
121	    pub fn deduplicating() -> Self {
122	        Self { deduplicate: true, ..Default::default() }
123	    }
124	
125	    /// Enter a new category.
126	    pub fn start_category(&mut self, category: Category) {
127	        self.category = Some(category);
128	    }
129	
130	    /// Reset the category.
131	    pub fn reset_category(&mut self) {
132	        self.category = None;
133	    }
134	
135	    /// Define a native function through a Rust type that shadows the function.
136	    #[track_caller]
137	    pub fn define_func<T: NativeFunc>(&mut self) -> &mut Binding {
138	        let data = T::data();
139	        self.define(data.name, Func::from(data))
140	    }
141	
142	    /// Define a native function with raw function data.
143	    #[track_caller]
144	    pub fn define_func_with_data(
145	        &mut self,
146	        data: &'static NativeFuncData,
147	    ) -> &mut Binding {
148	        self.define(data.name, Func::from(data))
149	    }
150	
151	    /// Define a native type.
152	    #[track_caller]
153	    pub fn define_type<T: NativeType>(&mut self) -> &mut Binding {
154	        let ty = T::ty();
155	        self.define(ty.short_name(), ty)
156	    }
157	
158	    /// Define a native element.
159	    #[track_caller]
160	    pub fn define_elem<T: NativeElement>(&mut self) -> &mut Binding {
161	        let elem = T::ELEM;
162	        self.define(elem.name(), elem)
163	    }
164	
165	    /// Define a built-in with compile-time known name and returns a mutable
166	    /// reference to it.
167	    ///
168	    /// When the name isn't compile-time known, you should instead use:
169	    /// - `Vm::bind` if you already have [`Binding`]
170	    /// - `Vm::define`  if you only have a [`Value`]
171	    /// - [`Scope::bind`](Self::bind) if you are not operating in the context of
172	    ///   a `Vm` or if you are binding to something that is not an AST
173	    ///   identifier (e.g. when constructing a dynamic
174	    ///   [`Module`](super::Module))
175	    #[track_caller]
176	    pub fn define(&mut self, name: &'static str, value: impl IntoValue) -> &mut Binding {
177	        #[cfg(debug_assertions)]
178	        if self.deduplicate && self.map.contains_key(name) {
179	            panic!("duplicate definition: {name}");
180	        }
181	
182	        let mut binding = Binding::detached(value);
183	        binding.category = self.category;
184	        self.bind(name.into(), binding)
185	    }
186	}
187	
188	/// Scope manipulation and access.
189	impl Scope {
190	    /// Inserts a binding into this scope and returns a mutable reference to it.
191	    ///
192	    /// Prefer `Vm::bind` if you are operating in the context of a `Vm`.
193	    pub fn bind(&mut self, name: EcoString, binding: Binding) -> &mut Binding {
194	        match self.map.entry(name) {
195	            Entry::Occupied(mut entry) => {
196	                entry.insert(binding);
197	                entry.into_mut()
198	            }
199	            Entry::Vacant(entry) => entry.insert(binding),
200	        }
201	    }
202	
203	    /// Try to access a binding immutably.
204	    pub fn get(&self, var: &str) -> Option<&Binding> {
205	        self.map.get(var)
206	    }
207	
208	    /// Try to access a binding mutably.
209	    pub fn get_mut(&mut self, var: &str) -> Option<&mut Binding> {
210	        self.map.get_mut(var)
211	    }
212	
213	    /// Iterate over all definitions.
214	    pub fn iter(&self) -> impl Iterator<Item = (&EcoString, &Binding)> {
215	        self.map.iter()
216	    }
217	}
