239	/// Defines the associated scope of a Rust type.
240	pub trait NativeScope {
241	    /// The constructor function for the type, if any.
242	    fn constructor() -> Option<&'static NativeFuncData>;
243	
244	    /// Get the associated scope for the type.
245	    fn scope() -> Scope;
246	}
